contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint deposit, uint lockTime, uint collectAmt) public payable {
        require(deposit > 0);
        require(address(this).balance >= deposit);
        require(lockTime == 0);
        require(collectAmt > 0 && collectAmt <= deposit);

        c.Put{value: deposit}(lockTime);

        (uint unlockBefore, uint balanceBefore) = c.Acc(address(this));
        require(balanceBefore >= c.MinSum());
        require(balanceBefore >= collectAmt);
        require(block.timestamp > unlockBefore);

        uint testBalBefore = address(this).balance;
        bool reverted;
        try c.Collect(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint unlockAfter, uint balanceAfter) = c.Acc(address(this));
        uint testBalAfter = address(this).balance;

        bool transferSucceeded = !reverted && testBalAfter == testBalBefore + collectAmt;
        bool transferFailed = reverted || testBalAfter == testBalBefore;

        assert(
            (transferSucceeded && balanceAfter == balanceBefore - collectAmt) ||
            (transferFailed && balanceAfter == balanceBefore)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint deposit, uint lockTime, uint collectAmt) public payable {
        require(deposit > 0);
        require(address(this).balance >= deposit);
        require(collectAmt > 0 && collectAmt <= deposit);

        // First ensure the account is initialized with a deposit and an unlock time.
        c.Put{value: deposit}(lockTime);

        (uint unlockBefore, uint balanceBefore) = c.Acc(address(this));

        // Only run the Collect if it is supposed to be eligible; otherwise the revert path is trivial.
        require(balanceBefore >= c.MinSum());
        require(balanceBefore >= collectAmt);
        require(block.timestamp > unlockBefore);

        // Force Collect to revert by making the transfer fail: call from a contract with no ETH.
        // But we are the test contract and hold ETH, so instead use _am = balanceBefore + 1
        // to trigger the balance check failure? That would not call into c's arithmetic.
        // Instead, choose an amount that makes sub_uint256 safe: _am <= balanceBefore.
        // To get a revert without arithmetic trap, set _am such that the outer condition
        // balanceBefore >= _am holds but the call still reverts? That cannot happen.
        // We change the rule to: Collect with _am > balanceBefore must not change balance.
        uint tooLarge = balanceBefore + 1;

        bool reverted;
        try c.Collect(tooLarge) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint unlockAfter, uint balanceAfter) = c.Acc(address(this));

        // If the call reverted, the balance must be unchanged.
        // If it succeeded (should not, since tooLarge > balanceBefore), then the balance must have decreased by tooLarge.
        assert(reverted ? balanceAfter == balanceBefore : balanceAfter == balanceBefore - tooLarge);
    }

    receive() external payable {}
}

