contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint lockTime, uint amount) public payable {
        require(amount > 0, "amount must be positive");
        require(address(this).balance >= amount, "not enough balance");

        c.Put{value: amount}(lockTime);

        uint balanceBefore = c.Acc(address(this));
        uint contractBalanceBefore = address(c).balance;
        uint senderBalanceBefore = address(this).balance;

        bool reverted;
        uint minSum = c.MinSum();
        uint unlockTime = c.Acc(address(this));

        try c.Collect(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balanceAfter = c.Acc(address(this));
        uint contractBalanceAfter = address(c).balance;
        uint senderBalanceAfter = address(this).balance;

        if (!reverted) {
            require(balanceBefore >= minSum, "precondition: balanceBefore >= MinSum");
            require(balanceBefore >= amount, "precondition: balanceBefore >= amount");
            require(block.timestamp > unlockTime, "precondition: time > unlockTime");

            assert(balanceAfter == balanceBefore - amount);
            assert(contractBalanceAfter == contractBalanceBefore - amount);
            assert(senderBalanceAfter == senderBalanceBefore + amount);
        } else {
            assert(balanceAfter == balanceBefore);
            assert(contractBalanceAfter == contractBalanceBefore);
            assert(senderBalanceAfter == senderBalanceBefore);
        }
    }

    receive() external payable {}
}

