contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint lockTime, uint collectAmount) public payable {
        // Precondition: amount must not exceed available Ether
        require(address(this).balance >= amount);

        // Initial state: get current contract balance and holder balance
        uint holderBalanceBefore = getHolderBalance(msg.sender);
        uint contractBalanceBefore = address(c).balance;

        // Perform Put
        c.Put{value: amount}(lockTime);

        // After Put, the Ether balance should increase by amount and holder balance should increase by amount
        uint holderBalanceAfterPut = getHolderBalance(msg.sender);
        uint contractBalanceAfterPut = address(c).balance;

        assert(holderBalanceAfterPut == holderBalanceBefore + amount);
        assert(contractBalanceAfterPut == contractBalanceBefore + amount);

        // Now try to Collect if unlocked and conditions met
        uint holderBalanceBeforeCollect = holderBalanceAfterPut;
        uint contractBalanceBeforeCollect = contractBalanceAfterPut;

        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            uint holderBalanceAfterCollect = getHolderBalance(msg.sender);
            uint contractBalanceAfterCollect = address(c).balance;

            assert(holderBalanceAfterCollect == holderBalanceBeforeCollect - collectAmount);
            assert(contractBalanceAfterCollect == contractBalanceBeforeCollect - collectAmount);
        }
    }

    function getHolderBalance(address addr) internal view returns (uint) {
        (uint unlockTime, uint balance) = c.Acc(addr);
        return balance;
    }

    receive() external payable {}
}

