contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    receive() external payable {}

    function run(address logAddr, uint lockTime, uint putValue, uint collectAmt) public payable {
        require(address(this).balance >= putValue);
        require(putValue >= collectAmt);
        require(collectAmt > 0);

        c.SetLogFile(logAddr);
        c.SetMinSum(0);
        c.Initialized();

        // Put first so that the caller has enough balance for a partial Collect.
        c.Put{value: putValue}(lockTime);

        (uint balBefore,) = c.Acc(address(this));
        uint cBalBefore = address(c).balance;

        bool collectReverted;
        try c.Collect(collectAmt) { collectReverted = false; } catch { collectReverted = true; }

        (uint balAfter,) = c.Acc(address(this));
        uint cBalAfter = address(c).balance;

        // General rule: a successful partial Collect reduces the stored balance by exactly
        // the withdrawn amount and decreases c's Ether balance by that same amount.
        assert(!collectReverted && balAfter == balBefore - collectAmt && cBalAfter == cBalBefore - collectAmt);
    }
}

