    constructor(C _c) {
        c = _c;
    }

    function run(uint _lockTime, uint amount) public payable {
        require(address(this).balance >= amount, "insufficient test balance");

        (uint beforeUnlockTime, uint beforeBalance) = c.Acc(address(this));

        c.Put{value: amount}(_lockTime);

        (uint afterUnlockTime, uint afterBalance) = c.Acc(address(this));

        uint expectedUnlockTime = beforeUnlockTime;
        if (block.timestamp + _lockTime > beforeUnlockTime) {
            expectedUnlockTime = block.timestamp + _lockTime;
        }

        assert(afterBalance == beforeBalance + amount && afterUnlockTime == expectedUnlockTime);
    }

    receive() external payable {}
}

contract InvMutTest {
