contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint lockTime, uint am) public payable {
        require(address(this).balance >= 2);

        c.SetMinSum(1);
        c.Initialized();

        uint beforeBalance;
        uint beforeUnlock;
        (beforeUnlock, beforeBalance) = c.Acc(address(this));

        c.Put{value: 1}(lockTime);

        uint afterBalance;
        uint afterUnlock;
        (afterUnlock, afterBalance) = c.Acc(address(this));

        bool putEffect = afterBalance == beforeBalance + 1 && afterUnlock >= block.timestamp + lockTime;

        bool collected;
        if (block.timestamp > afterUnlock && afterBalance >= am) {
            uint balanceBeforeCollect = afterBalance;
            uint etherBeforeCollect = address(c).balance;
            try c.Collect{value: 0}(am) {
                uint balanceAfterCollect;
                uint unlockAfterCollect;
                (unlockAfterCollect, balanceAfterCollect) = c.Acc(address(this));
                collected = balanceAfterCollect < balanceBeforeCollect && address(c).balance < etherBeforeCollect;
            } catch {
                collected = false;
            }
        } else {
            collected = true;
        }

        assert(putEffect && collected);
    }

    receive() external payable {}
}

