contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run() public payable {
        LogFile log = new LogFile();
        c.SetLogFile(address(log));

        c.Put{value: 0}(0);

        uint afterPutLen;
        {
            (bool _s, bytes memory _d) = address(log).staticcall(abi.encodeWithSignature("History(uint256)", uint256(0)));
            _s; _d;
        }

        uint lenBefore;
        {
            (bool _s, bytes memory _d) = address(log).staticcall(abi.encodeWithSignature("History(uint256)", uint256(0)));
            _s;
            if (_d.length >= 64) {
                (uint sender, string memory data, uint val, uint time) = abi.decode(_d, (uint256, string, uint256, uint256));
                data; val; time; sender;
            }
        }

        // Read history length via the auto-generated getter for the public array's index 0 repeatedly.
        // The public array History(uint256) returns the struct at that index and reverts if out of bounds;
        // we can probe its length by staticcalling increasing indices until it reverts.
        lenBefore = _historyLength(address(log));

        bool reverted;
        try c.Collect(0) { reverted = false; } catch { reverted = true; }

        require(!reverted);

        uint lenAfter = _historyLength(address(log));
        (uint balAfter,) = c.Acc(address(this));

        assert(lenAfter == lenBefore);
        assert(balAfter == 0);
    }

    function _historyLength(address logAddr) internal view returns (uint) {
        uint len = 0;
        while (true) {
            (bool ok,) = logAddr.staticcall(abi.encodeWithSignature("History(uint256)", len));
            if (!ok) break;
            len++;
            if (len > 1000) break;
        }
        return len;
    }

    receive() external payable {}
}

